-- ── 3. THE FOUNDING ──────────────────────────────────────────────────────────────────────────
do $$
declare
  r record;
begin
  for r in select * from npc_roster_0098 order by ord loop
    perform public.npc_found(r.spec);
  end loop;
end $$;

-- ── SELF-ASSERT ──────────────────────────────────────────────────────────────────────────────
do $$
declare
  v_n       int;
  v_fleets  int;
  v_bad     text[];
  v_pc      text[];
  v_def     text;
begin
  -- the counts, and the caps
  select count(*) into v_n from public.players where is_npc;
  select count(*) into v_fleets from public.npc_fleets;
  if v_n <> (select count(*) from npc_roster_0098)
     or v_fleets <> (select sum(jsonb_array_length(spec->'fleets')) from npc_roster_0098)
     or (select count(*) from public.npc_houses) <> v_n then
    raise exception '0098 self-assert FAIL: % companies and % fleets founded for a roster of % and %',
      v_n, v_fleets, (select count(*) from npc_roster_0098), (select sum(jsonb_array_length(spec->'fleets')) from npc_roster_0098);
  end if;
  if exists (select 1 from public.players p where p.is_npc and (
               (select count(*) from public.ships s where s.player_id = p.id) > public.wc_int('ship_max')
            or (select count(*) from public.fleets f where f.player_id = p.id) > public.wc_int('fleet_max')))
     or exists (select 1 from public.fleets f join public.players p on p.id = f.player_id and p.is_npc
                 where (select count(*) from public.ships s where s.fleet_id = f.id) > public.wc_int('fleet_ship_max')
                    or (select count(*) from public.ships s where s.fleet_id = f.id and s.is_flagship) <> 1) then
    raise exception '0098 self-assert FAIL: a merchant company breaks a cap or a fleet lacks one flagship';
  end if;

  -- the books: each purse is its capital, and the ledger says so
  select array_agg(p.company_name) into v_bad
    from public.players p join public.npc_houses h on h.player_id = p.id
   where p.is_npc and (p.ducats <> h.capital or public.ledger_sum(p.id) <> p.ducats);
  if v_bad is not null then
    raise exception '0098 self-assert FAIL: purse <> capital or ledger <> purse for %', v_bad;
  end if;

  -- every course passes the server's own verification, as cmd.do_sail calls it from a quay
  select array_agg(format('%s %s→%s: %s', sr.name, a.code, b.code, x.refusal)) into v_bad
    from public.standing_routes sr
    join public.players p on p.id = sr.player_id and p.is_npc
    join public.standing_route_stops s on s.route_id = sr.id
    join public.standing_route_stops s2 on s2.route_id = sr.id
         and s2.ord = (s.ord + 1) % (select count(*) from public.standing_route_stops c where c.route_id = sr.id)
    join public.ports a on a.id = s.port_id
    join public.ports b on b.id = s2.port_id
    join public.sea_reaches ra on ra.port_id = a.id
    join public.sea_reaches rb on rb.port_id = b.id
    cross join lateral (select voyage.path_refusal(s.course, ra.roadstead_lat, ra.roadstead_lon,
                                                   rb.roadstead_lat, rb.roadstead_lon,
                                                   public.wc_num('course_join_nm'), 25, 25) as refusal) x
   where x.refusal is not null;
  if v_bad is not null then
    raise exception '0098 self-assert FAIL: the server refuses merchant course(s): %', v_bad;
  end if;

  -- harbours only; no harbour twice in one loop
  if exists (select 1 from public.standing_routes sr join public.players p on p.id = sr.player_id and p.is_npc
               join public.standing_route_stops s on s.route_id = sr.id join public.ports po on po.id = s.port_id
              where po.kind <> 'HARBOUR')
     or exists (select 1 from public.standing_routes sr join public.players p on p.id = sr.player_id and p.is_npc
                  join public.standing_route_stops s on s.route_id = sr.id
                 group by sr.id, s.port_id having count(*) > 1) then
    raise exception '0098 self-assert FAIL: a merchant stop is not a harbour, or a loop calls at one twice';
  end if;

  -- DRAFT, with its positive control: the same test must refuse a nau (draft 3) at Seville (2).
  create temporary table draft_probe_0098 (fleet text, draft numeric, max_draft numeric);
  insert into draft_probe_0098
  select 'probe: a nau at Seville', c.draft, po.max_draft
    from public.ship_classes c, public.ports po where c.code = 'nau' and po.code = 'SVQ';
  insert into draft_probe_0098
  select f.name, (select max(c.draft) from public.ships s join public.ship_classes c on c.id = s.class_id where s.fleet_id = f.id),
         (select min(po.max_draft) from public.standing_route_stops st join public.ports po on po.id = st.port_id
           where st.route_id = nf.route_id)
    from public.npc_fleets nf join public.fleets f on f.id = nf.fleet_id;
  select array_agg(fleet) into v_pc from draft_probe_0098 where draft > max_draft and fleet like 'probe:%';
  select array_agg(fleet) into v_bad from draft_probe_0098 where draft > max_draft and fleet not like 'probe:%';
  if coalesce(array_length(v_pc, 1), 0) <> 1 then
    raise exception '0098 self-assert FAIL: the draft test cannot see its positive control';
  end if;
  if v_bad is not null then
    raise exception '0098 self-assert FAIL: a merchant fleet draws more than a stop takes: %', v_bad;
  end if;
  drop table draft_probe_0098;

  -- every quay on a loop can crew a fifth of the fleet back
  select array_agg(format('%s at %s', f.name, po.code)) into v_bad
    from public.npc_fleets nf join public.fleets f on f.id = nf.fleet_id
    join public.standing_route_stops st on st.route_id = nf.route_id join public.ports po on po.id = st.port_id
   where po.crew_pool < 0.2 * (select sum(c.crew_required) from public.ships s join public.ship_classes c on c.id = s.class_id where s.fleet_id = f.id);
  if v_bad is not null then
    raise exception '0098 self-assert FAIL: a quay cannot crew its merchant back: %', v_bad;
  end if;

  -- nations, names, blurbs
  if exists (select 1 from public.players where is_npc and nation_id is null) then
    raise exception '0098 self-assert FAIL: a merchant company has no nation';
  end if;
  if exists (select 1 from public.ships s join public.players p on p.id = s.player_id and p.is_npc
              group by s.player_id, lower(btrim(s.name)) having count(*) > 1) then
    raise exception '0098 self-assert FAIL: two hulls of one company share a name';
  end if;
  select array_agg(format('%s: %s', r.spec->>'company', g.code)) into v_bad
    from npc_roster_0098 r
    cross join lateral jsonb_array_elements_text(r.spec->'blurb_goods') g(code)
    join public.goods gd on gd.code = g.code
   where not (r.spec->'first_lap_goods' ? g.code)
      or strpos((select h.blurb from public.npc_houses h where h.roster_ord = (r.spec->>'roster_ord')::int), gd.name) = 0;
  if v_bad is not null then
    raise exception '0098 self-assert FAIL: a blurb names a good the measured first lap did not carry: %', v_bad;
  end if;

  -- nothing sails: no route assigned, every fleet docked at its stop 0, the switch off
  if exists (select 1 from public.npc_fleets nf join public.standing_routes sr on sr.id = nf.route_id where sr.fleet_id is not null)
     or exists (select 1 from public.npc_fleets nf join public.fleets f on f.id = nf.fleet_id
                  join public.standing_route_stops st on st.route_id = nf.route_id and st.ord = 0
                 where f.status <> 'DOCKED' or f.port_id is distinct from st.port_id)
     or exists (select 1 from public.standing_route_lines l join public.npc_fleets nf on nf.route_id = l.route_id)
     or public.npc_traders_on() then
    raise exception '0098 self-assert FAIL: a merchant was left assigned, at sea, away from home, with lines, or the switch is on';
  end if;
  if (select count(*) from public.officers where code in ('NPCPILOTPRT', 'NPCPURSERESP', 'NPCQMNLD', 'NPCSURGENG', 'NPCQMHAN', 'NPCPILOTGEN', 'NPCPURSERVEN', 'NPCSURGFRA', 'NPCPILOTOTT', 'NPCPURSERMUG', 'NPCPILOTMNG', 'NPCQMJPN')) <> 12 then
    raise exception '0098 self-assert FAIL: the lesser officers are not all in the catalogue';
  end if;

  -- npc_found still writes no game table by hand (0097's guard, re-read on the body that ran)
  v_def := pg_get_functiondef('public.npc_found(jsonb)'::regprocedure);
  if (select count(*) from regexp_matches(v_def, 'insert into public\.([a-z_]+)', 'g') m where m[1] not in ('npc_houses', 'npc_fleets')) > 0 then
    raise exception '0098 self-assert FAIL: npc_found writes a game table by hand';
  end if;

  raise notice '0098 self-assert ok: THE MERCHANT COMPANIES ARE FOUNDED. % companies, % fleets, % hulls, every cap held and one flagship a fleet; every purse is its capital and its ledger; every course passes voyage.path_refusal from the served roadsteads; harbours only, none twice in a loop; no fleet draws more than a stop takes (the test refused its nau-at-Seville control); every quay can crew a fifth of its merchant back; every company has a nation and distinct hull names; every blurb names only goods its measured first lap carried; nothing assigned, everyone docked at home with no lines, the switch OFF; % lesser officers in the catalogue; npc_found writes no game table by hand.',
    v_n, v_fleets, (select count(*) from public.ships s join public.players p on p.id = s.player_id and p.is_npc),
    12;
end $$;
